import sys, json, re, secrets, datetime

# A DOCUMENT IN A TURN BECOMES A FILE (file-space, GH #907). A turn arrives on
# `in_ingest` carrying `attachments: [{blob_id, mime_type, filename,
# size_bytes, sha256}]` -- a pointer into the colony's blob store, never the
# bytes (R-FJ-1): the channel wrote the document there. This cell births the
# first attachment as a file of this space under `/inbox/<YYYY-MM-DD>/<name>`
# (OR-FJ-I1), waits until `./derive` has its summary, and hands the turn on as
# route `turn` WITHOUT `attachments` and with ONE text turn right after the
# caption:
#
#   [file fh-<id>@<v12> "<name>", <n> pages: <oneline>]
#
# (without the page count for a document that is not a PDF). The model sees
# the address, never the bytes (OR-FJ-I2: a line, not a curator block). The
# caption and everything else of the turn go on unchanged, hop keys included.
#
# POINTER ONLY. This cell does not declare `consumes.body.attachments`, so it
# never sees the bytes; it hands the reference on and the cell that needs the
# bytes reads the blob itself: `./write` (args `attachment`) for any document,
# `./extract` for a PDF, which reads the pages and sends the `create` to
# `./write` itself. Neither the bytes nor the pages ever sit in a `pending`
# row, a hop or a context of this cell -- a 20 MiB PDF has more than 1 MiB of
# text, and a header row of the message log stays <= 8 KiB.
#
# THE WAY. (1) Park the request, stake a claim on the name and ask the store
# which of the candidate paths are taken. (2) A PDF goes to `./extract`
# (`{attachments: [ref], path, mime}`), which sends the `create` on; any
# other document is a `create` on `in_write` from here -- caller `ingest`,
# `notify` '1', `args.attachment` 0. (3) `answer` re-keys the row to the
# file's id; a `path_taken` searches again (at most TRIES times). (4)
# `derived` -- sent by `./derive` on success AND on failure (OR-FJ-G7) --
# reads the file's `derived` parts for the page count and releases the turn.
# A failure anywhere releases it too, with
# `[file "<name>" could not be stored: <code>]`: a turn is never swallowed.
#
# TWO ROWS in `pending` per document, both `cell = 'ingest'`: the request
# (`op_id`: the turn without `attachments`, the reference, name, mime, hop
# keys, candidates, tries) and its claim (`c:<op_id>`, the name's first
# candidate path in `body`, `phase` `claim` or `path:<chosen path>`). The
# claim goes with `answer ok`, the request with the released turn.
#
# THE CLAIM (GH #907 review I-3). Two documents of one name in one poll: both
# path searches run before either `create`, and `write` checks a path by a
# read in one phase and inserts it in a later one, so both would be born
# under the same path. A store bundle runs its operations in order before the
# next message, so the claim inserted in step (1) is seen by every later
# search of the same name, and a search sees only the claims made before its
# own: a search skips one free candidate per earlier claim that has not
# chosen yet, and treats a chosen path as taken.
#
# CORRELATION. `op_id` is this cell's own (`ing-<16 hex>`); a store answer
# is recognised by `context.cur_phase` on the store's own edge, every other
# answer by its route plus `op_id` (write) or `file` (derive -- `derived`
# carries no `op_id`, so step 3 re-keys the parked row to `w:<file>`).
#
# A name is made safe for a path: `/` and `\` become `_`, control characters
# go, at most 120 characters (the extension kept), a taken path gets ` (2)`,
# ` (3)` ... before the extension.

doc = json.load(sys.stdin)
d = doc.get("body") or {}
P = doc.get("params") or {}
header = (doc.get("envelope") or {}).get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}

ME = "ingest"
TRIES = 3
PDF = "application/pdf"
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
NAME_MAX = 120
EXT_MAX = 16
SUFFIX_MAX = 20
PARTS_MAX = 1000
ONELINE_MAX = 120


# ============================================================ PURE
SAFE = {"/": "_", "\\": "_", '"': "'", "[": "(", "]": ")"}


def norm_name(name):
    """A file name safe as the last segment of a path."""
    # `"`, `[` and `]` would make the address line ambiguous to read.
    s = "".join(SAFE.get(ch, ch) for ch in str(name or "")
                if ord(ch) >= 32 and ord(ch) != 127).strip()
    if s in ("", ".", ".."):
        s = "document" if s == "" else "_"
    if len(s) > NAME_MAX:
        stem, ext = split_ext(s)
        if len(ext) > EXT_MAX:
            stem, ext = s, ""
        s = stem[:NAME_MAX - len(ext)].rstrip() + ext
    return s


def split_ext(name):
    """`a.b.pdf` -> (`a.b`, `.pdf`); a leading dot is no extension."""
    i = name.rfind(".")
    if i <= 0:
        return name, ""
    return name[:i], name[i:]


def with_suffix(name, n):
    """The n-th candidate of `name`: itself, then `stem (n)ext`."""
    if n <= 1:
        return name
    stem, ext = split_ext(name)
    return "%s (%d)%s" % (stem, n, ext)


def inbox_paths(name, day):
    base = "/inbox/%s/" % day
    return [base + with_suffix(name, n) for n in range(1, SUFFIX_MAX + 1)]


def free_path(candidates, taken, ahead=0):
    """The free candidate this search owns: it skips one free candidate per
    earlier claim that has not chosen yet (`ahead`)."""
    taken = set(taken)
    free = [p for p in candidates if p not in taken]
    if ahead < len(free):
        return free[ahead]
    head, _, last = candidates[0].rpartition("/")
    stem, ext = split_ext(last)
    return "%s/%s (%s)%s" % (head, stem, secrets.token_hex(3), ext)


def address_line(file, version, name, pages, oneline, pdf):
    """The line the turn carries instead of the file element."""
    one = " ".join(str(oneline or "").split())[:ONELINE_MAX]
    head = '[file %s@%s "%s"' % (file, str(version or "")[:12], name)
    if pdf and pages:
        head += ", %d page%s" % (pages, "" if pages == 1 else "s")
        return head + (": " + one if one else "") + "]"
    return head + (": " + one if one else "") + "]"


def failure_line(name, code):
    return '[file "%s" could not be stored: %s]' % (name, code)


def first_ref(turn):
    """The first attachment of the turn as a reference -- anything a reader
    may have added (`data_b64`, `error`) left out -- or None."""
    atts = turn.get("attachments")
    if not isinstance(atts, list) or not atts:
        return None
    a = atts[0]
    if not isinstance(a, dict):
        return {}
    return {k: v for k, v in a.items() if k not in ("data_b64", "error")}


def with_line(turn, text):
    """The turn without `attachments`, `text` as one text turn right after
    the caption (the first text turn), or last when there is none."""
    out = {k: v for k, v in turn.items() if k != "attachments"}
    msgs = list(out.get("messages") or [])
    at = len(msgs)
    for i, m in enumerate(msgs):
        if isinstance(m, dict) and m.get("type") == "text":
            at = i + 1
            break
    msgs.insert(at, {"origin": "user", "type": "text", "text": text})
    out["messages"] = msgs
    return out


def ahead_of(claims, me, at, retry):
    """(paths chosen by other claims, how many others have not chosen yet and
    come first). On the first search the store returns only earlier claims;
    on a retry every other open claim counts, since those came first too or
    will see this one's choice."""
    chosen, waiting = [], 0
    for c in claims:
        if not isinstance(c, dict) or c.get("op_id") == me:
            continue
        ph = str(c.get("phase") or "")
        if ph.startswith("path:"):
            chosen.append(ph[5:])
        elif retry or (str(c.get("at") or ""), str(c.get("op_id"))) < (at, me):
            waiting += 1
    return chosen, waiting


# ============================================================ PLUMBING
def emit(msgs):
    # OR-FJ.L.8: every emission leaves as a UBF body -- one with none of
    # `messages`/`system`/`attachments` is dead-lettered (`invalid_ubf_body`).
    for m in msgs:
        if isinstance(m, dict) and not any(k in m for k in ("messages", "system", "attachments")):
            m["messages"] = []
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("file-space/ingest: %s\n" % reason)
    emit([])


def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def store(ops, phase):
    return {"header": {"route": "ingest_store", "phase": phase, "reply_cell": ME},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def legs(body):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": ""}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": ""})
                leg["error_code"] = str(r.get("error_code") or "")
    elif len(out) == 1:
        next(iter(out.values()))["error_code"] = str(hop.get("error_code") or "")
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return p if isinstance(p, list) else []


def mine(key):
    return {"op_id": key, "cell": ME}


def put(S, phase, key=None):
    return ("p-put", {"operation": "update", "table": "pending",
                      "set": {"phase": phase, "body": json.dumps(S, sort_keys=True)},
                      "where": mine(key or S["op_id"])})


def echo(key):
    """The request row."""
    return ("p-echo", {"operation": "select", "table": "pending",
                       "columns": ["op_id", "phase", "body"],
                       "where": {"op_id": key, "cell": ME}, "limit": 1})


def search(S):
    """Which candidate paths are taken, and the claims on this name."""
    return [("paths", {"operation": "select", "table": "files", "columns": ["path"],
                       "where": {"path": {"in": S["candidates"]}, "tomb": ""},
                       "limit": SUFFIX_MAX}),
            ("claims", {"operation": "select", "table": "pending",
                        "columns": ["op_id", "phase", "at"],
                        "where": {"cell": ME, "body": S["candidates"][0]}, "limit": 100})]


def drops(key, op_id):
    """Every row of one document: the request (under `key`) and the claim."""
    return ("p-drop", {"operation": "delete", "table": "pending",
                       "where": {"op_id": {"in": [key, "c:" + op_id]},
                                 "cell": ME}})


def release(S, text, key=None):
    """The turn goes on without `attachments`, `text` after its caption;
    every row of the document goes."""
    h = dict(S.get("hop") or {})
    h["route"] = "turn"
    msg = with_line(S["turn"], text)
    msg["header"] = h
    out = [msg]
    if key:
        out.append(store([drops(key, S["op_id"])], "done"))
    emit(out)


# ============================================================ LANES
def on_turn():
    turn = {k: v for k, v in d.items() if k != "header"}
    ref = first_ref(turn)
    h = {k: v for k, v in hop.items() if k != "route"}
    if ref is None:
        # No attachment after all: the turn goes on untouched.
        turn["header"] = dict(h, route="turn")
        emit([turn])
    name = norm_name(ref.get("filename"))
    mime = str(ref.get("mime_type") or "") or "application/octet-stream"
    kept = {k: v for k, v in turn.items() if k != "attachments"}
    S = {"op_id": "ing-" + secrets.token_hex(8), "turn": kept, "ref": ref, "name": name,
         "mime": mime, "hop": h}
    if not ref:
        # An entry that is no object: nothing to point at.
        release(S, failure_line(name, "bad_request"))
    day = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%d")
    S["candidates"] = inbox_paths(name, day)
    S["at"] = now()
    S["tries"] = 0
    S["taken"] = []

    def row(key, phase, body):
        return {"operation": "insert", "table": "pending",
                "row": {"op_id": key, "cell": ME, "phase": phase, "body": body, "at": S["at"]}}

    ops = [("p-put", row(S["op_id"], "paths", json.dumps(S, sort_keys=True))),
           ("c-put", row("c:" + S["op_id"], "claim", S["candidates"][0])),
           echo(S["op_id"])] + search(S)
    emit([store(ops, "paths")])


def create_msg(S):
    """`create` on `in_write` with the reference: `./write` reads the blob."""
    args = {"path": S["path"], "mime": S["mime"], "notify": "1", "attachment": 0}
    return {"header": {"route": "in_write", "op": "create", "op_id": S["op_id"],
                       "caller": ME, "notify": "1"},
            "messages": [], "op": "create", "args": args, "attachments": [S["ref"]]}


def on_paths(S, lg):
    me = "c:" + S["op_id"]
    chosen, waiting = ahead_of(rows(lg, "claims"), me, S["at"], S["tries"] > 0)
    taken = [r.get("path") for r in rows(lg, "paths")] + chosen + S["taken"]
    S["path"] = free_path(S["candidates"], taken, waiting)
    S["name"] = S["path"].rpartition("/")[2]
    claim = ("c-put", {"operation": "update", "table": "pending",
                       "set": {"phase": "path:" + S["path"]}, "where": mine(me)})
    if S["mime"] != PDF:
        emit([store([put(S, "create"), claim], "noop"), create_msg(S)])
    # A PDF: `./extract` reads the blob, splits the pages and sends the
    # `create` to `./write` itself -- the pages never pass this cell. A
    # `path_taken` retry asks `./extract` again (a second pdftotext run):
    # rare, and cheaper than parking the pages anywhere.
    ask = {"header": {"route": "in_extract", "op_id": S["op_id"]}, "messages": [],
           "attachments": [S["ref"]], "path": S["path"], "mime": S["mime"]}
    emit([store([put(S, "extract"), claim], "noop"), ask])


def on_answer():
    op_id = str(hop.get("op_id") or d.get("op_id") or "")
    if d.get("ok") is True and d.get("file"):
        # Re-key the row to the file: `derived` names the file, not the op_id.
        # The path is in `files` now, so the claim goes.
        ops = [("r-key", {"operation": "update", "table": "pending",
                          "set": {"op_id": "w:" + str(d["file"]),
                                  "phase": "wait:" + str(d.get("version") or "")},
                          "where": mine(op_id)}),
               ("c-drop", {"operation": "delete", "table": "pending",
                           "where": mine("c:" + op_id)})]
        emit([store(ops, "noop")])
    code = str((d.get("error") or {}).get("code") or "store_failed")
    ops = [("f-put", {"operation": "update", "table": "pending",
                      "set": {"phase": "fail:" + code}, "where": mine(op_id)}),
           echo(op_id)]
    emit([store(ops, "failed")])


def on_derived():
    key = "w:" + str(d.get("file") or "")
    info = {"file": str(d.get("file") or ""), "version": str(d.get("version") or ""),
            "ok": bool(d.get("ok")), "oneline": str(d.get("oneline") or "")}
    # The page count is the number of `derived` text parts of the born file
    # (`part` only, never the text): a fresh file has one version.
    ops = [("d-put", {"operation": "update", "table": "pending",
                      "set": {"phase": "d:" + json.dumps(info)}, "where": mine(key)}),
           echo(key),
           ("parts", {"operation": "select", "table": "derived", "columns": ["part"],
                      "where": {"file": info["file"], "kind": "text"}, "limit": PARTS_MAX})]
    emit([store(ops, "derived")])


def on_store(phase):
    if phase in ("noop", "done"):
        emit([])
    lg = legs(d)
    found = rows(lg, "p-echo")
    row = found[0] if found and isinstance(found[0], dict) else None
    S = None
    if row:
        try:
            S = json.loads(row.get("body") or "null")
        except Exception:
            S = None
    if not isinstance(S, dict):
        park("store answer in phase %r without its parked request -- dropped" % phase)
    bad = sorted(cid for cid, leg in lg.items() if leg["error_code"])
    if bad:
        sys.stderr.write("file-space/ingest: store refused %s in %s\n" % (", ".join(bad), phase))
        release(S, failure_line(S["name"], "store_error"), row.get("op_id"))
    mark = str(row.get("phase") or "")
    if phase == "paths":
        on_paths(S, lg)
    if phase == "failed" and mark == "fail:path_taken" and S["tries"] + 1 < TRIES:
        # Taken after all (a writer outside this cell, or a claim that came
        # later on a retry): search again with the same reference.
        S["tries"] += 1
        S["taken"].append(S["path"])
        ops = [put(S, "paths"),
               ("c-put", {"operation": "update", "table": "pending",
                          "set": {"phase": "claim"}, "where": mine("c:" + S["op_id"])}),
               echo(S["op_id"])] + search(S)
        emit([store(ops, "paths")])
    if phase == "failed" and mark.startswith("fail:"):
        release(S, failure_line(S["name"], mark[5:]), row.get("op_id"))
    if phase == "derived" and mark.startswith("d:"):
        info = json.loads(mark[2:])
        oneline = info["oneline"] if info.get("ok") else ""
        pages = len(rows(lg, "parts"))
        release(S, address_line(info["file"], info["version"], S["name"], pages,
                                oneline, S["mime"] == PDF), row.get("op_id"))
    park("phase %r with row mark %r -- dropped" % (phase, mark[:20]))


lane = str(hop.get("route") or "")
if lane == "in_ingest":
    on_turn()
if lane == "answer":
    on_answer()
if lane == "derived":
    on_derived()
if lane:
    park("unknown lane %r -- dropped" % lane)
if not hop.get("operation"):
    park("a message with neither a lane nor a store answer -- dropped")
on_store(str(ctx.get("cur_phase") or ""))
